<template>
  <div class="card" :class="{ 'has-background-light': application.status === 'not-configured' }">
    <div class="card-content">
      <div class="media">
        <div class="media-left">
          <figure class="image is-48x48">
            <img
              :src="assetUrl('tracking', `${application.name}.png`)"
              :alt="$gettext(application.name)"
              class="rounded"
              :class="{ 'grayed-out': application.status === 'not-configured' }"
            />
          </figure>
        </div>
        <div class="media-content">
          <p class="is-4 has-text-weight-bold">{{ $gettext(application.name) }}</p>
          <a :href="application.website" class="is-6 external-link" target="_blank" v-translate>Go to website</a>
          <span
            class="status is-size-1"
            :class="application.status === 'configured' ? 'has-text-success' : 'has-text-warning'"
            :title="$gettext('Configured')"
            v-if="application.status !== 'not-configured'"
            >{{ application.status === 'configured' ? '✔' : '⚠' }}</span
          >
        </div>
      </div>
    </div>
    <footer class="card-footer">
      <button type="button" class="card-footer-item" @click="configure()" v-if="canConnect">
        <fa-icon icon="plug"></fa-icon>&nbsp;{{ $gettext('Connect') }}
      </button>
      <button type="button" class="card-footer-item" @click="configure()" v-if="canRefresh">
        <fa-icon icon="rotate"></fa-icon>&nbsp;{{ $gettext('Refresh') }}
      </button>
      <button type="button" class="card-footer-item" @click="revoke()" v-if="canRevoke">
        <fa-icon icon="trash"></fa-icon>&nbsp;{{ $gettext('Revoke') }}
      </button>
    </footer>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';

import { assetUrl } from '@/js/asset-urls';

const props = defineProps({
  application: {
    type: Object,
    required: true,
  },
});

const emit = defineEmits(['configure', 'revoke']);

const canRefresh = computed(() => props.application.status !== 'not-configured');
const canConnect = computed(() => props.application.status === 'not-configured');
const canRevoke = computed(() => props.application.status !== 'not-configured');

function revoke() {
  emit('revoke');
}

function configure() {
  emit('configure');
}
</script>

<style scoped>
