  &:not(:last-child) {
    border-right: 1px solid hsl(0, 0%, 93%);
  }

  &:hover {
    color: var(--c2c-grey-darker);
  }
}

.status {
  position: absolute;
  top: 20px;
  right: 30px;
  cursor: help;
}
</style>
